Future<void> main() async {
  const dsn = 'YOUR_DSN';
  await Sentry.init(
    (options) {
      options.dsn = dsn;
      options.tracesSampleRate = 1.0;
    },
  );
  final executor = NativeDatabase.memory().interceptWith(
    SentryQueryInterceptor(databaseName: 'my_db_name'),
  );
  final db = AppDatabase(executor);
}
